package com.sakti.banking.controller; import com.sakti.banking.audit.AuditEvent; import com.sakti.banking.service.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/security") public class SecurityController {private final SecurityCacheService cache;private final AuditService audit;public SecurityController(SecurityCacheService c,AuditService a){cache=c;audit=a;} @PostMapping("/otp") public Map<String,String> otp(Authentication a){String otp=cache.issueOtp(a.getName());return Map.of("status","ISSUED","demoOtp",otp,"expiresIn","5 minutes");} @GetMapping("/activity") public List<AuditEvent> activity(Authentication a){return audit.recent(a.getName());}}
